public readonly record struct GridCoord(int X, int Y, int Level = 0) : IComparable<GridCoord>
{
    public int ManhattanDistance(GridCoord other) =>
        Math.Abs(X - other.X) + Math.Abs(Y - other.Y) + Math.Abs(Level - other.Level) * 2;

    public GridCoord Offset(CardinalDirection direction) => direction switch
    {
        CardinalDirection.North => this with { Y = Y + 1 },
        CardinalDirection.East => this with { X = X + 1 },
        CardinalDirection.South => this with { Y = Y - 1 },
        CardinalDirection.West => this with { X = X - 1 },
        _ => this,
    };

    public int CompareTo(GridCoord other)
    {
        var level = Level.CompareTo(other.Level);
        if (level != 0) return level;
        var y = Y.CompareTo(other.Y);
        return y != 0 ? y : X.CompareTo(other.X);
    }
}

