/// Owns all tactical spatial invariants: cells, occupancy, reservations and
/// explicit traversal links.
public sealed class TacticalBoard
{
    private readonly Dictionary<GridCoord, TacticalCell> _cells = new();
    private readonly Dictionary<GridCoord, string> _occupants = new();
    private readonly Dictionary<string, GridCoord> _positions = new(StringComparer.Ordinal);
    private readonly Dictionary<GridCoord, string> _reservations = new();
    private readonly Dictionary<GridCoord, SortedSet<GridCoord>> _links = new();

    public IEnumerable<TacticalCell> Cells => _cells.Values.OrderBy(cell => cell.Coord);

    public void AddOrReplaceCell(TacticalCell cell) => _cells[cell.Coord] = cell;

    public bool TryGetCell(GridCoord coord, out TacticalCell cell) =>
        _cells.TryGetValue(coord, out cell!);

    public TacticalCell GetCell(GridCoord coord) =>
        _cells.TryGetValue(coord, out var cell)
            ? cell
            : throw new KeyNotFoundException($"Tactical cell {coord} does not exist.");

    public string? OccupantAt(GridCoord coord) =>
        _occupants.TryGetValue(coord, out var entity) ? entity : null;

    public GridCoord? PositionOf(string entityId) =>
        _positions.TryGetValue(entityId, out var coord) ? coord : null;

    public bool CanEnter(GridCoord coord, string? entityId = null)
    {
        if (!_cells.TryGetValue(coord, out var cell) || !cell.Walkable) return false;
        if (_occupants.TryGetValue(coord, out var occupant) &&
            !StringComparer.Ordinal.Equals(occupant, entityId)) return false;
        return !_reservations.TryGetValue(coord, out var owner) ||
               StringComparer.Ordinal.Equals(owner, entityId);
    }

    public void Place(string entityId, GridCoord coord)
    {
        RequireEnterable(entityId, coord);
        if (_positions.Remove(entityId, out var previous)) _occupants.Remove(previous);
        _positions[entityId] = coord;
        _occupants[coord] = entityId;
    }

    public void Move(string entityId, GridCoord coord)
    {
        if (!_positions.ContainsKey(entityId))
            throw new InvalidOperationException($"Tactical entity '{entityId}' is not on the board.");
        Place(entityId, coord);
    }

    public bool Remove(string entityId)
    {
        if (!_positions.Remove(entityId, out var coord)) return false;
        _occupants.Remove(coord);
        ReleaseReservations(entityId);
        return true;
    }

    public void Reserve(string entityId, GridCoord coord)
    {
        RequireEnterable(entityId, coord);
        ReleaseReservations(entityId);
        _reservations[coord] = entityId;
    }

    public void ReleaseReservations(string entityId)
    {
        foreach (var coord in _reservations
                     .Where(pair => StringComparer.Ordinal.Equals(pair.Value, entityId))
                     .Select(pair => pair.Key)
                     .ToArray())
            _reservations.Remove(coord);
    }

    public void AddLink(GridCoord from, GridCoord to, bool bidirectional = true)
    {
        GetCell(from);
        GetCell(to);
        LinkOneWay(from, to);
        if (bidirectional) LinkOneWay(to, from);
    }

    public IEnumerable<GridCoord> Neighbors(GridCoord coord)
    {
        var result = new SortedSet<GridCoord>();
        foreach (var direction in Enum.GetValues<CardinalDirection>())
        {
            var neighbor = coord.Offset(direction);
            if (_cells.ContainsKey(neighbor)) result.Add(neighbor);
        }
        if (_links.TryGetValue(coord, out var links)) result.UnionWith(links);
        return result;
    }

    public CoverKind CoverBetween(GridCoord from, GridCoord to)
    {
        var direction = DirectionBetween(from, to);
        if (direction is null) return CoverKind.None;
        var left = GetCell(from).CoverAt(direction.Value);
        var right = GetCell(to).CoverAt(Opposite(direction.Value));
        return (CoverKind)Math.Max((int)left, (int)right);
    }

    public TacticalBoardSnapshot CreateSnapshot() => new()
    {
        Cells = Cells.Select(CloneCell).ToList(),
        Occupants = _occupants
            .OrderBy(pair => pair.Key)
            .Select(pair => new BoardOccupant(pair.Key, pair.Value))
            .ToList(),
        Reservations = _reservations
            .OrderBy(pair => pair.Key)
            .Select(pair => new BoardOccupant(pair.Key, pair.Value))
            .ToList(),
        Links = _links
            .SelectMany(pair => pair.Value
                .Where(to => pair.Key.CompareTo(to) <= 0)
                .Select(to => new BoardLink(pair.Key, to)))
            .OrderBy(link => link.From)
            .ThenBy(link => link.To)
            .ToList(),
    };

    public static TacticalBoard FromSnapshot(TacticalBoardSnapshot snapshot)
    {
        var board = new TacticalBoard();
        foreach (var cell in snapshot.Cells) board.AddOrReplaceCell(CloneCell(cell));
        foreach (var link in snapshot.Links) board.AddLink(link.From, link.To);
        foreach (var occupant in snapshot.Occupants) board.Place(occupant.EntityId, occupant.Coord);
        foreach (var reservation in snapshot.Reservations)
            board.Reserve(reservation.EntityId, reservation.Coord);
        return board;
    }

    private void RequireEnterable(string entityId, GridCoord coord)
    {
        if (!_cells.TryGetValue(coord, out var cell))
            throw new KeyNotFoundException($"Tactical cell {coord} does not exist.");
        if (!cell.Walkable) throw new InvalidOperationException($"Tactical cell {coord} is blocked.");
        if (_occupants.TryGetValue(coord, out var occupant) &&
            !StringComparer.Ordinal.Equals(occupant, entityId))
            throw new InvalidOperationException($"Tactical cell {coord} is occupied by '{occupant}'.");
        if (_reservations.TryGetValue(coord, out var owner) &&
            !StringComparer.Ordinal.Equals(owner, entityId))
            throw new InvalidOperationException($"Tactical cell {coord} is reserved by '{owner}'.");
    }

    private void LinkOneWay(GridCoord from, GridCoord to)
    {
        if (!_links.TryGetValue(from, out var links))
            _links[from] = links = new SortedSet<GridCoord>();
        links.Add(to);
    }

    private static TacticalCell CloneCell(TacticalCell cell) => new()
    {
        Coord = cell.Coord,
        WorldPosition = cell.WorldPosition,
        MovementCost = cell.MovementCost,
        Walkable = cell.Walkable,
        BlocksSight = cell.BlocksSight,
        Cover = new Dictionary<CardinalDirection, CoverKind>(cell.Cover),
    };

    private static CardinalDirection? DirectionBetween(GridCoord from, GridCoord to)
    {
        if (from.Level != to.Level) return null;
        foreach (var direction in Enum.GetValues<CardinalDirection>())
            if (from.Offset(direction) == to) return direction;
        return null;
    }

    private static CardinalDirection Opposite(CardinalDirection direction) => direction switch
    {
        CardinalDirection.North => CardinalDirection.South,
        CardinalDirection.East => CardinalDirection.West,
        CardinalDirection.South => CardinalDirection.North,
        _ => CardinalDirection.East,
    };
}

