public sealed class DefaultMovementCostPolicy : IMovementCostPolicy
{
    public int? StepCost(TacticalBoard board, GridCoord from, GridCoord to, string? actorId)
    {
        if (!board.CanEnter(to, actorId)) return null;
        return Math.Max(1, board.GetCell(to).MovementCost);
