public sealed class ReachabilityMap
{
    private readonly Dictionary<GridCoord, int> _costs;
    private readonly Dictionary<GridCoord, GridCoord> _previous;

    internal ReachabilityMap(
        Dictionary<GridCoord, int> costs,
        Dictionary<GridCoord, GridCoord> previous)
    {
        _costs = costs;
        _previous = previous;
    }

    public IEnumerable<KeyValuePair<GridCoord, int>> Cells =>
        _costs.OrderBy(pair => pair.Key);

    public int? CostAt(GridCoord coord) => _costs.TryGetValue(coord, out var cost) ? cost : null;

    public TacticalPath? PathTo(GridCoord start, GridCoord goal)
    {
        if (!_costs.TryGetValue(goal, out var cost)) return null;
        return new TacticalPath { Cells = Reconstruct(_previous, start, goal), TotalCost = cost };
    }

    internal static List<GridCoord> Reconstruct(
        IReadOnlyDictionary<GridCoord, GridCoord> previous,
        GridCoord start,
        GridCoord goal)
    {
        var cells = new List<GridCoord> { goal };
        var current = goal;
        while (current != start)
        {
            if (!previous.TryGetValue(current, out current))
                throw new InvalidOperationException("Path predecessor chain is incomplete.");
            cells.Add(current);
        }
        cells.Reverse();
        return cells;
    }
}

/// Deterministic A* and action-point reachability service.
public sealed class TacticalPathfinder
{
    private readonly IMovementCostPolicy _movement;

    public TacticalPathfinder(IMovementCostPolicy? movement = null) =>
        _movement = movement ?? new DefaultMovementCostPolicy();

    public TacticalPath? FindPath(
        TacticalBoard board,
        GridCoord start,
        GridCoord goal,
        string? actorId = null)
    {
        if (!board.TryGetCell(start, out _) || !board.TryGetCell(goal, out _)) return null;
        var costs = new Dictionary<GridCoord, int> { [start] = 0 };
        var previous = new Dictionary<GridCoord, GridCoord>();
        var frontier = new PriorityQueue<(GridCoord Coord, int Cost), (int Total, int Cost, int Level, int Y, int X)>();
        frontier.Enqueue((start, 0), (start.ManhattanDistance(goal), 0, start.Level, start.Y, start.X));
        while (frontier.TryDequeue(out var node, out _))
        {
            if (!costs.TryGetValue(node.Coord, out var known) || known != node.Cost) continue;
            if (node.Coord == goal)
                return new TacticalPath
                {
                    Cells = ReachabilityMap.Reconstruct(previous, start, goal),
                    TotalCost = known,
                };
            foreach (var neighbor in board.Neighbors(node.Coord))
            {
                var step = _movement.StepCost(board, node.Coord, neighbor, actorId);
                if (step is null) continue;
                var next = checked(known + step.Value);
                if (costs.TryGetValue(neighbor, out var current) && next >= current) continue;
                costs[neighbor] = next;
                previous[neighbor] = node.Coord;
                frontier.Enqueue(
                    (neighbor, next),
                    (next + neighbor.ManhattanDistance(goal), next, neighbor.Level, neighbor.Y, neighbor.X));
            }
        }
        return null;
    }

    public ReachabilityMap Reachable(
        TacticalBoard board,
        GridCoord start,
        int movementBudget,
        string? actorId = null)
    {
        var costs = new Dictionary<GridCoord, int>();
        var previous = new Dictionary<GridCoord, GridCoord>();
        if (!board.TryGetCell(start, out _) || movementBudget < 0)
            return new ReachabilityMap(costs, previous);
        costs[start] = 0;
        var frontier = new PriorityQueue<(GridCoord Coord, int Cost), (int Cost, int Level, int Y, int X)>();
        frontier.Enqueue((start, 0), (0, start.Level, start.Y, start.X));
        while (frontier.TryDequeue(out var node, out _))
        {
            if (costs[node.Coord] != node.Cost) continue;
            foreach (var neighbor in board.Neighbors(node.Coord))
            {
                var step = _movement.StepCost(board, node.Coord, neighbor, actorId);
                if (step is null) continue;
                var next = checked(node.Cost + step.Value);
                if (next > movementBudget ||
                    costs.TryGetValue(neighbor, out var current) && next >= current) continue;
                costs[neighbor] = next;
                previous[neighbor] = node.Coord;
                frontier.Enqueue((neighbor, next), (next, neighbor.Level, neighbor.Y, neighbor.X));
            }
        }
        return new ReachabilityMap(costs, previous);
    }
}

public interface ILineOfSightPolicy
{
    bool HasLineOfSight(TacticalBoard board, GridCoord origin, GridCoord target);
}

public sealed class GridLineOfSightPolicy : ILineOfSightPolicy
{
    public bool HasLineOfSight(TacticalBoard board, GridCoord origin, GridCoord target)
    {
        if (origin.Level != target.Level ||
            !board.TryGetCell(origin, out _) ||
            !board.TryGetCell(target, out _)) return false;
        foreach (var coord in RasterLine(origin, target).Skip(1))
        {
            if (coord == target) break;
            if (!board.TryGetCell(coord, out var cell) || cell.BlocksSight) return false;
        }
        return true;
    }

    private static IEnumerable<GridCoord> RasterLine(GridCoord start, GridCoord end)
    {
        var x = start.X;
        var y = start.Y;
        var dx = Math.Abs(end.X - start.X);
        var sx = start.X < end.X ? 1 : -1;
        var dy = -Math.Abs(end.Y - start.Y);
        var sy = start.Y < end.Y ? 1 : -1;
        var error = dx + dy;
        while (true)
        {
            yield return new GridCoord(x, y, start.Level);
            if (x == end.X && y == end.Y) yield break;
            var twice = error * 2;
            if (twice >= dy) { error += dy; x += sx; }
            if (twice <= dx) { error += dx; y += sy; }
        }
    }
}

public readonly record struct VisibilityEntry(int Faction, GridCoord Coord, VisibilityState State);

public sealed class VisibilityMap
{
    private readonly Dictionary<int, Dictionary<GridCoord, VisibilityState>> _factions = new();

    public VisibilityState StateAt(int faction, GridCoord coord) =>
        _factions.TryGetValue(faction, out var cells) &&
        cells.TryGetValue(coord, out var state) ? state : VisibilityState.Unseen;

    public void Update(
        int faction,
        TacticalBoard board,
        IEnumerable<(GridCoord Origin, int Range)> observers,
        ILineOfSightPolicy? lineOfSight = null)
    {
        lineOfSight ??= new GridLineOfSightPolicy();
        if (!_factions.TryGetValue(faction, out var cells))
            _factions[faction] = cells = new Dictionary<GridCoord, VisibilityState>();
        foreach (var coord in cells
                     .Where(pair => pair.Value == VisibilityState.Visible)
                     .Select(pair => pair.Key)
                     .ToArray())
            cells[coord] = VisibilityState.Explored;
        foreach (var (origin, range) in observers)
            foreach (var cell in board.Cells)
                if (origin.ManhattanDistance(cell.Coord) <= range &&
                    lineOfSight.HasLineOfSight(board, origin, cell.Coord))
                    cells[cell.Coord] = VisibilityState.Visible;
    }

    public List<VisibilityEntry> CreateSnapshot() =>
        _factions
            .SelectMany(faction => faction.Value.Select(cell =>
                new VisibilityEntry(faction.Key, cell.Key, cell.Value)))
            .OrderBy(entry => entry.Faction)
            .ThenBy(entry => entry.Coord)
            .ToList();

    public static VisibilityMap FromSnapshot(IEnumerable<VisibilityEntry> entries)
    {
        var result = new VisibilityMap();
        foreach (var entry in entries)
        {
            if (!result._factions.TryGetValue(entry.Faction, out var cells))
                result._factions[entry.Faction] = cells = new();
            cells[entry.Coord] = entry.State;
        }
        return result;
    }
}

