/// Command queue plus deterministic initiative coordinator.
public sealed class TurnDirector
{
    private readonly Dictionary<string, TurnParticipant> _participants = new(StringComparer.Ordinal);
    private readonly Queue<TacticalAction> _actions = new();
    private readonly Queue<TacticalAction> _reactions = new();
    private List<string> _order = new();
    private int _activeIndex;

    public int Round { get; private set; }
    public TurnPhase Phase { get; private set; }
    public string? ActiveActor => _activeIndex < _order.Count ? _order[_activeIndex] : null;
    public IEnumerable<TurnParticipant> Participants =>
        _participants.Values.OrderBy(participant => participant.EntityId, StringComparer.Ordinal);

    public void AddOrReplace(TurnParticipant participant) =>
        _participants[participant.EntityId] = participant;

    public IReadOnlyList<TacticalEvent> Start()
    {
        _order = _participants.Values
            .Where(participant => participant.Active)
            .OrderByDescending(participant => participant.Initiative)
            .ThenBy(participant => participant.EntityId, StringComparer.Ordinal)
            .Select(participant => participant.EntityId)
            .ToList();
        _activeIndex = 0;
        Round = 1;
        RefreshActionPoints();
        if (_order.Count == 0)
        {
            Phase = TurnPhase.Complete;
            return new TacticalEvent[] { new TacticalEvent.EncounterStarted(), new TacticalEvent.EncounterCompleted() };
        }
        Phase = TurnPhase.Acting;
        return new TacticalEvent[]
        {
            new TacticalEvent.EncounterStarted(),
            new TacticalEvent.RoundStarted(Round),
            new TacticalEvent.TurnStarted(ActiveActor!),
        };
    }

    public IReadOnlyList<TacticalEvent> Submit(ITacticalCommand command) => command switch
    {
        QueueActionCommand queue => Queue(queue.Action, queue.IsReaction),
        EndTurnCommand end => EndTurn(end.ActorId),
        _ => throw new ArgumentOutOfRangeException(nameof(command)),
    };

    public IReadOnlyList<TacticalEvent> ResolveNext(ITacticalActionExecutor executor)
    {
        TacticalAction? action = null;
        if (_reactions.TryDequeue(out var reaction))
        {
            action = reaction;
            Phase = TurnPhase.Reaction;
        }
        else if (_actions.TryDequeue(out var queued))
        {
            action = queued;
            Phase = TurnPhase.Resolving;
        }
        if (action is null)
        {
            Phase = TurnPhase.Acting;
            return Array.Empty<TacticalEvent>();
        }
        var events = executor.Execute(action).ToList();
        events.Add(new TacticalEvent.ActionResolved(action.Id));
        if (_reactions.Count == 0 && _actions.Count == 0) Phase = TurnPhase.Acting;
        return events;
    }

    public TurnDirectorSnapshot CreateSnapshot() => new()
    {
        Participants = Participants.Select(participant => new TurnParticipantSnapshot(
            participant.EntityId,
            participant.Faction,
            participant.Initiative,
            participant.MaxActionPoints,
            participant.ActionPoints,
            participant.Active)).ToList(),
        Order = _order.ToList(),
        ActiveIndex = _activeIndex,
        Round = Round,
        Phase = Phase,
        Actions = _actions.Select(ToSnapshot).ToList(),
        Reactions = _reactions.Select(ToSnapshot).ToList(),
    };

    public static TurnDirector FromSnapshot(TurnDirectorSnapshot snapshot)
    {
        var director = new TurnDirector
        {
            _order = snapshot.Order.ToList(),
            _activeIndex = snapshot.ActiveIndex,
            Round = snapshot.Round,
            Phase = snapshot.Phase,
        };
        foreach (var saved in snapshot.Participants)
            director.AddOrReplace(new TurnParticipant
            {
                EntityId = saved.EntityId,
                Faction = saved.Faction,
                Initiative = saved.Initiative,
                MaxActionPoints = saved.MaxActionPoints,
                ActionPoints = saved.ActionPoints,
                Active = saved.Active,
            });
        foreach (var action in snapshot.Actions) director._actions.Enqueue(FromSnapshot(action));
        foreach (var action in snapshot.Reactions) director._reactions.Enqueue(FromSnapshot(action));
        if (director._activeIndex < 0 || director._activeIndex >= Math.Max(1, director._order.Count))
            throw new JsonException("Turn snapshot active index is outside its initiative order.");
        if (director._order.Any(id => !director._participants.ContainsKey(id)))
            throw new JsonException("Turn snapshot initiative order references an unknown participant.");
        return director;
    }

    private IReadOnlyList<TacticalEvent> Queue(TacticalAction action, bool reaction)
    {
        if (!reaction && !StringComparer.Ordinal.Equals(ActiveActor, action.ActorId))
            throw new InvalidOperationException($"'{action.ActorId}' is not the active actor.");
        if (!_participants.TryGetValue(action.ActorId, out var participant))
            throw new KeyNotFoundException($"Participant '{action.ActorId}' does not exist.");
        if (participant.ActionPoints < action.ActionPointCost)
            throw new InvalidOperationException($"Participant '{action.ActorId}' has insufficient AP.");
        participant.ActionPoints -= action.ActionPointCost;
        (reaction ? _reactions : _actions).Enqueue(action);
        return new TacticalEvent[] { new TacticalEvent.ActionQueued(action.Id) };
    }

    private IReadOnlyList<TacticalEvent> EndTurn(string actorId)
    {
        if (!StringComparer.Ordinal.Equals(ActiveActor, actorId))
            throw new InvalidOperationException($"'{actorId}' is not the active actor.");
        var events = new List<TacticalEvent> { new TacticalEvent.TurnEnded(actorId) };
        _activeIndex++;
        if (_activeIndex >= _order.Count)
        {
            _activeIndex = 0;
            Round++;
            RefreshActionPoints();
            events.Add(new TacticalEvent.RoundStarted(Round));
        }
        events.Add(new TacticalEvent.TurnStarted(ActiveActor!));
        return events;
    }

    private void RefreshActionPoints()
    {
        foreach (var participant in _participants.Values)
            participant.ActionPoints = participant.MaxActionPoints;
    }

    private static TacticalActionSnapshot ToSnapshot(TacticalAction action)
    {
        var (kind, cell, entity) = action.Target switch
        {
            ActionTarget.Cell target => ("cell", (GridCoord?)target.Coord, (string?)null),
            ActionTarget.Entity target => ("entity", null, target.EntityId),
            _ => ("none", null, null),
        };
        return new TacticalActionSnapshot(
            action.Id,
            action.ActorId,
            action.Kind,
            action.ActionPointCost,
            kind,
            cell,
            entity,
            action.Payload?.ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.Ordinal)
                ?? new Dictionary<string, string>(StringComparer.Ordinal));
    }

    private static TacticalAction FromSnapshot(TacticalActionSnapshot action)
    {
        ActionTarget target = action.TargetKind switch
        {
            "cell" when action.TargetCell is { } cell => new ActionTarget.Cell(cell),
            "entity" when action.TargetEntityId is { } entity => new ActionTarget.Entity(entity),
            "none" => new ActionTarget.None(),
            _ => throw new JsonException($"Unknown or incomplete action target '{action.TargetKind}'."),
        };
        return new TacticalAction(
            action.Id,
            action.ActorId,
            action.Kind,
            action.ActionPointCost,
            target,
            action.Payload);
    }
}

public sealed class CombatStats
{
    public int MaxHealth { get; init; }
    public int Aim { get; init; }
    public int Defense { get; init; }
    public int Armor { get; init; }
    public int Mobility { get; init; }
    public int Will { get; init; }
}

public sealed class StatusEffect
{
    public string Key { get; init; } = "";
    public int RemainingRounds { get; set; }
    public int Stacks { get; set; } = 1;
}

public sealed class Combatant
{
    public string EntityId { get; init; } = "";
    public CombatStats Stats { get; init; } = new();
    public int Health { get; set; }
    public Dictionary<string, StatusEffect> Statuses { get; init; } = new(StringComparer.Ordinal);
    public Dictionary<string, int> Cooldowns { get; init; } = new(StringComparer.Ordinal);
    [JsonIgnore] public bool IsAlive => Health > 0;

    public static Combatant Create(string entityId, CombatStats stats) => new()
    {
        EntityId = entityId,
        Stats = stats,
        Health = stats.MaxHealth,
    };

    public void TickRound()
    {
        foreach (var key in Cooldowns.Keys.ToArray())
            if (--Cooldowns[key] <= 0) Cooldowns.Remove(key);
        foreach (var (key, status) in Statuses.ToArray())
            if (--status.RemainingRounds <= 0) Statuses.Remove(key);
    }
}

public readonly record struct WeaponProfile(
    int BaseDamage,
    int ArmorPiercing,
    int Range,
    int Accuracy,
    int CriticalChanceBasisPoints,
    int CriticalBonusDamage);

public readonly record struct AttackContext(int Distance, CoverKind TargetCover, int ElevationDelta);

public readonly record struct CombatOutcome(
    bool Hit,
    bool Critical,
    int HitChanceBasisPoints,
    int Roll,
    int Damage,
    int TargetHealth,
    bool TargetKilled);

public interface IHitChancePolicy
{
    int GetHitChanceBasisPoints(
        Combatant attacker,
        Combatant target,
        WeaponProfile weapon,
        AttackContext context);
}

public sealed class DefaultHitChancePolicy : IHitChancePolicy
{
    public int GetHitChanceBasisPoints(
        Combatant attacker,
        Combatant target,
        WeaponProfile weapon,
        AttackContext context)
    {
        var rangePenalty = Math.Max(0, context.Distance - weapon.Range) * 5;
        var coverPenalty = context.TargetCover switch
        {
            CoverKind.Half => 20,
            CoverKind.Full => 40,
            _ => 0,
        };
        var elevationBonus = Math.Clamp(context.ElevationDelta, -2, 2) * 10;
        var percent = 65 + attacker.Stats.Aim + weapon.Accuracy - target.Stats.Defense
                      - coverPenalty - rangePenalty + elevationBonus;
        return Math.Clamp(percent, 0, 100) * 100;
    }
}

// Compatibility wrapper retained for projects compiled against Script API 0.10.
public sealed class DeterministicRandom : Engine.Gameplay.DeterministicRandom
{
    public DeterministicRandom(ulong seed) : base(seed) { }
}

public sealed class CombatResolver
{
    private readonly IHitChancePolicy _hitChance;

    public CombatResolver(IHitChancePolicy? hitChance = null) =>
        _hitChance = hitChance ?? new DefaultHitChancePolicy();

    public CombatOutcome ResolveAttack(
        Combatant attacker,
        Combatant target,
        WeaponProfile weapon,
        AttackContext context,
        DeterministicRandom random)
    {
        var chance = _hitChance.GetHitChanceBasisPoints(attacker, target, weapon, context);
        var roll = random.RollBasisPoints();
        var hit = roll < chance;
        var critical = hit && random.RollBasisPoints() < weapon.CriticalChanceBasisPoints;
        var rawDamage = hit
            ? weapon.BaseDamage + (critical ? weapon.CriticalBonusDamage : 0)
            : 0;
        var armor = Math.Max(0, target.Stats.Armor - weapon.ArmorPiercing);
        var damage = hit ? Math.Max(1, rawDamage - armor) : 0;
        target.Health = Math.Max(0, target.Health - damage);
        return new CombatOutcome(
            hit, critical, chance, roll, damage, target.Health, !target.IsAlive);
    }
}

public sealed class UtilityOption
{
    public string Key { get; init; } = "";
    public string ActorId { get; init; } = "";
    public string? TargetEntityId { get; init; }
    public GridCoord? TargetCell { get; init; }
    public float BaseScore { get; init; } = 1f;
    public Dictionary<string, float> Facts { get; init; } = new(StringComparer.Ordinal);
}

public interface IUtilityConsideration
{
    string Key { get; }
    float Evaluate(UtilityOption option);
}

public sealed record ScoredUtilityOption(
    UtilityOption Option,
    float Score,
    IReadOnlyDictionary<string, float> Considerations);

public sealed class UtilityBrain
{
    private readonly List<IUtilityConsideration> _considerations = new();

    public UtilityBrain Add(IUtilityConsideration consideration)
    {
        _considerations.Add(consideration);
        return this;
    }

    public ScoredUtilityOption Score(UtilityOption option)
    {
        var score = option.BaseScore;
        var values = new SortedDictionary<string, float>(StringComparer.Ordinal);
        foreach (var consideration in _considerations)
        {
            var value = Math.Clamp(consideration.Evaluate(option), 0f, 1f);
            values[consideration.Key] = value;
            score *= value;
        }
        return new ScoredUtilityOption(option, score, values);
    }

    public ScoredUtilityOption? Choose(IEnumerable<UtilityOption> options) =>
        options.Select(Score)
            .OrderByDescending(option => option.Score)
            .ThenBy(option => option.Option.Key, StringComparer.Ordinal)
            .FirstOrDefault();
}

public sealed class FactCurve : IUtilityConsideration
{
    public string Key { get; init; } = "";
    public string Fact { get; init; } = "";
    public float InputMin { get; init; }
    public float InputMax { get; init; } = 1f;
    public bool Invert { get; init; }

    public float Evaluate(UtilityOption option)
    {
        option.Facts.TryGetValue(Fact, out var value);
        var range = InputMax - InputMin;
        var normalized = Math.Abs(range) <= float.Epsilon
            ? 0f
            : Math.Clamp((value - InputMin) / range, 0f, 1f);
        return Invert ? 1f - normalized : normalized;
    }
}

public sealed class TacticalSessionSnapshot
{
    public TacticalBoardSnapshot Board { get; init; } = new();
    public TurnDirectorSnapshot Turns { get; init; } = new();
    public List<VisibilityEntry> Visibility { get; init; } = new();
    public List<Combatant> Combatants { get; init; } = new();
    public ulong RandomState { get; init; }
}

/// Save-friendly façade for project-owned tactical state.
public sealed class TacticalSession
{
    public TacticalBoard Board { get; private set; } = new();
    public TurnDirector Turns { get; private set; } = new();
    public VisibilityMap Visibility { get; private set; } = new();
    public Dictionary<string, Combatant> Combatants { get; private set; } = new(StringComparer.Ordinal);
    public DeterministicRandom Random { get; private set; }

    public TacticalSession(ulong seed = 0) => Random = new DeterministicRandom(seed);

    public string ToJson(JsonSerializerOptions? options = null) =>
        JsonSerializer.Serialize(new TacticalSessionSnapshot
        {
            Board = Board.CreateSnapshot(),
            Turns = Turns.CreateSnapshot(),
            Visibility = Visibility.CreateSnapshot(),
            Combatants = Combatants.Values.OrderBy(unit => unit.EntityId, StringComparer.Ordinal).ToList(),
            RandomState = Random.State,
        }, options);

    public static TacticalSession FromJson(string json, JsonSerializerOptions? options = null)
    {
        var snapshot = JsonSerializer.Deserialize<TacticalSessionSnapshot>(json, options)
                       ?? throw new JsonException("Tactical session payload is empty.");
        return new TacticalSession(snapshot.RandomState)
        {
            Board = TacticalBoard.FromSnapshot(snapshot.Board),
            Turns = TurnDirector.FromSnapshot(snapshot.Turns),
            Visibility = VisibilityMap.FromSnapshot(snapshot.Visibility),
            Combatants = snapshot.Combatants.ToDictionary(
                unit => unit.EntityId, unit => unit, StringComparer.Ordinal),
        };
    }
}
